plugins {
    id("dev.onyx.java-conventions")
    kotlin("jvm") version Config.KOTLIN_VERSION
}

dependencies {
    implementation(project(":onyx-database"))
    implementation(project(":onyx-remote-database"))
    implementation(project(":onyx-remote-driver"))
    testImplementation("org.jetbrains.kotlin:kotlin-test-junit:${Config.KOTLIN_VERSION}")
    testImplementation(kotlin("test"))
}

description = "dev.onyx:onyx-database-tests"

tasks.getByName<Test>("test") {
    useJUnit()
    minHeapSize = "2048m"
    maxHeapSize = "4096m"
}

// Deliberately separate from check/test: a normal run writes two 100+ GB databases plus indexes.
tasks.register<Test>("largeStoreBenchmark") {
    description = "Compare MEMORY_MAPPED_FILE and FILE with 100+ GB of small PerformanceEntity records."
    group = "benchmark"
    useJUnit()
    testClassesDirs = sourceSets.test.get().output.classesDirs
    classpath = sourceSets.test.get().runtimeClasspath
    filter { includeTestsMatching("database.store.LargeStoreBenchmarkTest") }
    workingDir(rootProject.projectDir)
    minHeapSize = "512m"
    maxHeapSize = "2g"
    maxParallelForks = 1
    systemProperty("onyx.benchmark.largeStore.enabled", "true")
    listOf(
        "smoke", "dataGB", "dataGiB", "payloadBytes", "operations", "warmupOperations", "rounds", "seed",
        "directory", "keepDatabases"
    ).forEach { name ->
        providers.gradleProperty("largeStoreBenchmark.$name").orNull?.let {
            systemProperty("onyx.benchmark.largeStore.$name", it)
        }
    }
    outputs.upToDateWhen { false }
    outputs.doNotCacheIf("Benchmark timings must be measured on every invocation") { true }
    testLogging.showStandardStreams = true
}

project.tasks.publish.configure {
    this.enabled = false
}

// This module is an internal integration-test fixture. Disabling only the lifecycle `publish`
// task is insufficient because the shared Central finalizer depends on concrete repository tasks.
tasks.withType<PublishToMavenRepository>().configureEach {
    enabled = false
}
tasks.withType<PublishToMavenLocal>().configureEach {
    enabled = false
}
tasks.named("centralFinalize") {
    enabled = false
}

java {
